  assert.ok(result.value.length > 0);
  assert.ok(result.value[0].base > 0);
});

test('vatSummary with multiple VAT rates', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
