  if (result.value.length > 1) {
    const rates = result.value.map(r => r.rate);
    const uniqueRates = new Set(rates);
    assert.equal(uniqueRates.size, rates.length);
  }
});

test('vatSummary rate sorting is descending', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const issued = issueInvoice(draft, []).value;
  const result = vatSummary([issued]);

  for (let i = 1; i < result.value.length; i++) {
    assert.ok(result.value[i - 1].rate >= result.value[i].rate);
  }
});

test('vatSummary sums base and vat for same rate', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2026-09-01');
  const invoice2 = createAndIssueInvoice('C-001', '2026-09-05');

  const result = vatSummary([invoice1, invoice2]);

  assert.ok(result.value.length > 0);
  assert.ok(result.value[0].base > 0);
  assert.ok(result.value[0].vat > 0);
});

test('vatSummary with voucher on invoice', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const withVoucher = applyVoucher(draft, { code: 'PROMO', amount: 5000 }).value;
  const issued = issueInvoice(withVoucher, []).value;

  const result = vatSummary([issued]);

  assert.ok(result.value.length > 0);
});

test('vatSummary calculates VAT correctly', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const result = vatSummary([invoice]);

  assert.ok(result.value.length > 0);
  const { rate, base, vat } = result.value[0];
  const expectedVat = Math.round(base * rate / 100);
  assert.equal(vat, expectedVat);
});

