// VAT Summary Tests
import { vatSummary } from '../src/reports.js';

test('vatSummary returns empty array when no invoices', () => {
  const result = vatSummary([]);

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('vatSummary returns empty array when no matching invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = vatSummary([draft]);

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('vatSummary returns single VAT rate for single line', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const result = vatSummary([invoice]);

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(typeof result.value[0].rate, 'number');
  assert.ok(result.value[0].base > 0);
  assert.ok(result.value[0].vat > 0);
});

test('vatSummary returns rate field', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const result = vatSummary([invoice]);

  assert.ok('rate' in result.value[0]);
  assert.equal(typeof result.value[0].rate, 'number');
});

test('vatSummary returns base field', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const result = vatSummary([invoice]);

  assert.ok('base' in result.value[0]);
  assert.equal(typeof result.value[0].base, 'number');
});

test('vatSummary returns vat field', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const result = vatSummary([invoice]);

  assert.ok('vat' in result.value[0]);
  assert.equal(typeof result.value[0].vat, 'number');
});

test('vatSummary aggregates multiple lines same VAT rate', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const issued = issueInvoice(draft, []).value;
  const result = vatSummary([issued]);

  assert.equal(result.value.length, 1);
});

test('vatSummary sorts by rate high to low', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const issued = issueInvoice(draft, []).value;
  const result = vatSummary([issued]);

  if (result.value.length > 1) {
    assert.ok(result.value[0].rate >= result.value[1].rate);
  }
});

test('vatSummary filters out draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

