import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices, vatSummary } from '../src/reports.js';

function createAndIssueInvoice(customerId, issueDate, terms = 'NET30') {
  const result = createInvoice({
    customerId,
    issueDate,
    terms,
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  if (!result.ok) throw new Error(`Failed to create invoice: ${result.error}`);
  const issued = issueInvoice(result.value, []);
  if (!issued.ok) throw new Error(`Failed to issue invoice: ${issued.error}`);
  return issued.value;
}

